    const string Template="InvisibilityTemplate",Manager="InvisibilityManagerSettings",Filter="CamouflageDetectorObjectFilter";
    static uint[] ExpectedFlags(string text,string[] names,int[] values,int words){uint[] result=new uint[words];foreach(string token in text.Split(new char[]{' '},StringSplitOptions.RemoveEmptyEntries)){int index=Array.IndexOf(names,token);if(index<0)throw new Exception("Independent default enum missing");int bit=values[index];if(bit>=0&&bit<words*32)result[bit/32]|=1u<<(bit%32);}return result;}
    static void Flags(byte[] bytes,int off,bool big,uint[] expected,string label){for(int i=0;i<expected.Length;++i)Check(Word(bytes,off+4*i,big)==expected[i],label+"/word"+i);}
    static string FilterXml(string attrs,string children){return "<"+Filter+" "+attrs+">"+children+"</"+Filter+">";}
    static void Abi(TargetPlatform p){bool big=p!=TargetPlatform.Win32;
        AssetBuffer d=Test("ABI/defaultTemplate",Root(Template,"",""),p);Check(d.InstanceData.Length==240,"template240");
        Flags(d.InstanceData,4,big,ExpectedFlags("PREATTACK_A FIRING_A FIRING_OR_PREATTACK_A RELOADING_A USING_WEAPON_A PREATTACK_B FIRING_B FIRING_OR_PREATTACK_B RELOADING_B USING_WEAPON_B PREATTACK_C FIRING_C FIRING_OR_PREATTACK_C RELOADING_C USING_WEAPON_C",ModelNames,ModelValues,15),"default15 weapon model conditions");Flags(d.InstanceData,64,big,new uint[15],"default model exceptions");Flags(d.InstanceData,124,big,ExpectedFlags("IS_FIRING_WEAPON IS_AIMING_WEAPON SPECIAL_ABILITY_PACKING_UNPACKING_OR_USING USING_ABILITY",StatusNames,StatusValues,7),"default status");Flags(d.InstanceData,172,big,ExpectedFlags("IS_ATTACKING",StatusNames,StatusValues,7),"default detectable");Flags(d.InstanceData,204,big,new uint[7],"default required");Check(Word(d.InstanceData,152,big)==0&&Word(d.InstanceData,156,big)==0&&Word(d.InstanceData,160,big)==0&&Word(d.InstanceData,200,big)==0&&Word(d.InstanceData,232,big)==0&&Word(d.InstanceData,236,big)==0,"default scalars/count/pointer");Offsets(d.ImportsData,new uint[0],big,"default no imports");Offsets(d.RelocationData,new uint[0],big,"default no pointers");
        AssetBuffer s=Test("ABI/completeTemplate",Root(Template,"CamouflageLevel='17' InvisibilityType='CAMOUFLAGE' Options='ALLOW_NEAR_TREES CAN_ATTACK_WHILE_ACTIVE' EnteringStealthFX='FX\\9' LeavingStealthFX='FX\\1' NoStealthForAttackWindow='500ms' ForbiddenConditions='' ForbiddenConditionExceptions='ALL' ForbiddenStatus='' HintDetectableStates='' RequiredStatus='ALL'","<IgnoreTreeCheckUpgrade>MixedCase</IgnoreTreeCheckUpgrade><IgnoreTreeCheckUpgrade/><IgnoreTreeCheckUpgrade>MIXEDCASE</IgnoreTreeCheckUpgrade>"),p);
        Check(s.InstanceData.Length==252&&Word(s.InstanceData,152,big)==17&&Word(s.InstanceData,156,big)==1&&Word(s.InstanceData,160,big)==17&&Word(s.InstanceData,164,big)==10&&Word(s.InstanceData,168,big)==2&&Word(s.InstanceData,200,big)==0x3f000000u,"template scalar/ref offsets");Check(Word(s.InstanceData,232,big)==3&&Word(s.InstanceData,236,big)==240&&Word(s.InstanceData,240,big)==Word(s.InstanceData,248,big)&&Word(s.InstanceData,244,big)==0,"upgrade4byte weak list");for(int i=0;i<15;++i)Check(Word(s.InstanceData,64+4*i,big)==UInt32.MaxValue,"ALL includes model padding");for(int i=0;i<7;++i)Check(Word(s.InstanceData,204+4*i,big)==UInt32.MaxValue,"ALL includes status padding");Offsets(s.ImportsData,new uint[]{168,164},big,"FX imports index order");Offsets(s.RelocationData,new uint[]{236},big,"upgrade pointer");
        AssetBuffer absent=Test("ABI/filterAbsent",Root(Manager,"",""),p);Check(absent.InstanceData.Length==116,"manager116 absent filter");for(int at=4;at<116;at+=4)Check(Word(absent.InstanceData,at,big)==0,"absent inline filter zero");
        AssetBuffer empty=Test("ABI/filterPresentEmpty",Root(Manager,"",FilterXml("","")),p);Check(empty.InstanceData.Length==116&&Word(empty.InstanceData,8,big)==3&&Word(empty.InstanceData,16,big)==0,"present filter inline ruleNONE3 no allocation");Offsets(empty.RelocationData,new uint[0],big,"empty inline filter no pointers");
        AssetBuffer filter=Test("ABI/fullInlineFilter",Root(Manager,"",FilterXml("id='MixedCase' Rule='ANY' Relationship='ALLIES ENEMIES' Alignment='GOOD' Include='INFANTRY' Exclude='STRUCTURE' StatusBitFlags='' StatusBitFlagsExclude=''","<IncludeThing>MixedCase</IncludeThing><ExcludeThing>MIXEDCASE</ExcludeThing>")),p);
        Check(filter.InstanceData.Length==180&&Word(filter.InstanceData,8,big)==2&&Word(filter.InstanceData,12,big)==3&&Word(filter.InstanceData,16,big)==2,"inline filter116+28+28+4+4");Check(Word(filter.InstanceData,92,big)==116&&Word(filter.InstanceData,96,big)==144&&Word(filter.InstanceData,100,big)==1&&Word(filter.InstanceData,104,big)==172&&Word(filter.InstanceData,108,big)==1&&Word(filter.InstanceData,112,big)==176,"inline pointers/count offsets");Check(Word(filter.InstanceData,4,big)==Word(filter.InstanceData,172,big)&&Word(filter.InstanceData,172,big)==Word(filter.InstanceData,176,big),"filter id and weakThing same hash");Offsets(filter.RelocationData,new uint[]{92,96,104,112},big,"inline child allocation order");Offsets(filter.ImportsData,new uint[0],big,"weak things no imports");
    }
    static void Matrix(TargetPlatform p){bool big=p!=TargetPlatform.Win32;
